Definition minvA (mo : Model) : Prop := minv (strip mo) /\ m_vm_materialized mo = [].

Lemma minvA_minv : forall mo, minvA mo -> minv (strip mo).
Proof.
ltac2:(KReplay.run1 (kr_t_NodesA ()) ["Defs"] "h01Hh12H0h22_Hh32mop;1p;3p-1R0p10000p4p710p9P0p1000Sp4p710p9P0p1001?R1p4p710p9P0P1p4p7210p9P0P1p4p73110p9P0p1001]p4p710p9P0p1002Dp4p710R1p9P0p1002bp4p710p9P0p1003ZR2p4p710p8P0P2p4p7210p8P0p10047p4p710p8P0p1004WR2p4p710p8P0P2p4p7210p8p10055p4p70R2g005eR0p4p710R3p8P2p1006?p4p710R4p8P2p1006[p4p710R5p8P2p10079p4p7210R6p8P2p1007VR7p4p710R8p8P2P7p4p7210R7p8P2P1p8p10083p4p710P1p8p1008Pp4p70R2P3p8P2p1009>p4p7210p8P2P4p8P2P5p8P2P6p8P2P8p8P2P7p8P2P1p8P2p1009Zp4p710p8p100:7p4p7210P1p8p100:cp4p70R2P3p8P2P4p8P2P5p8P2P6p8P2P8p8P2P7p8P2P1p8g00;Yj19Tg00<Oj12Tg00=Ej11Tg00>8j10Tg00>]j18Tg00?;j17Tg00?^j16Tg00@>j13Tg00A>j15TP0j34Tg00A^f0R0#9g00BTf1R1#2#1g00Bo#0#0#0#0#0#0#8#7R2#6R7%31%52R234f2#2#1P0f3#2#1f4#3=472P1W2W0P1P0O2n2001000000120000000W1W3o"). Qed.

