Lemma succ_ok_nil : forall A n mo mo_ eff moX mo' evs,
  nstepA n mo (rstrip eff) mo' evs ->
  syscall_effect_accesses eff = [] ->
  mrel A mo' moX ->
  succ_ok A n mo mo_ eff moX evs.
Proof.
