Section PerNodeA.
Variable segs : list Segment.
Variable NMAX : nat.

(* [comment removed for export] *)
Definition node_factsA (A : alw) (RNG : footprint) (ms : machine_state) (mo mo_ : Model) (n : node) : Prop :=
  exists x8, ms_svc_pending ms = Some x8 /\
  (forall eff moX evs, check_syscall (sys_input segs ms x8) eff mo_ = CheckOk moX evs -> succ_ok A n mo mo_ eff moX evs) /\
  (forall eff mo' evs, nstepA n mo eff mo' evs ->
     exists effk moX, check_syscall (sys_input segs ms x8) effk mo_ = CheckOk moX evs /\ rstrip effk = eff) /\
  (forall eff, check_syscall (sys_input segs ms x8) eff mo_ <> CheckUnmodeled) /\
  (forall eff mo' evs, nstepA n mo eff mo' evs -> m_halted mo' = None /\ minvA mo') /\
  (forall eff mo1 mo2 evs1 evs2, nstepA n mo eff mo1 evs1 -> nstepA n mo eff mo2 evs2 -> mo1 = mo2).

Definition node_factsA_ns (A : alw) (RNG : footprint) (ms : machine_state) (mo mo_ : Model) (n : node) : Prop :=
  exists x8, ms_svc_pending ms = Some x8 /\
  (forall eff moX evs, check_syscall (sys_input segs ms x8) eff mo_ = CheckOk moX evs ->
     ~ spurious_refusal_cfg ACFG (sys_input segs ms x8) mo_ eff -> succ_ok A n mo mo_ eff moX evs) /\
  (forall eff moX evs, check_syscall (sys_input segs ms x8) eff mo_ = CheckOk moX evs -> m_halted moX = None) /\
  (forall eff mo' evs, nstepA n mo eff mo' evs ->
     exists effk moX, check_syscall (sys_input segs ms x8) effk mo_ = CheckOk moX evs /\ rstrip effk = eff
                      /\ ~ spurious_refusal_cfg ACFG (sys_input segs ms x8) mo_ effk) /\
  (forall eff, check_syscall (sys_input segs ms x8) eff mo_ <> CheckUnmodeled) /\
  (forall eff mo' evs, nstepA n mo eff mo' evs -> m_halted mo' = None /\ minvA mo') /\
  (forall eff mo1 mo2 evs1 evs2, nstepA n mo eff mo1 evs1 -> nstepA n mo eff mo2 evs2 -> mo1 = mo2).

Lemma succ_ok_halted : forall A n mo mo_ eff moX evs,
  succ_ok A n mo mo_ eff moX evs ->
  (forall eff mo' evs, nstepA n mo eff mo' evs -> m_halted mo' = None) ->
  m_halted moX = None.
Proof.
  intros A n mo mo_ eff moX evs (mo' & moY & Hn & HmatY & (SB & _)) Hhalt.
  pose proof (Hhalt _ _ _ Hn) as Hh0.
  pose proof (materialize_model_accesses_frame _ _ _ HmatY) as (_ & _ & _ & _ & _ & PR & _).
  pose proof (same_but_mat_halted _ _ SB) as E. unfold m_halted in *. rewrite PR in E. congruence.
Qed.

Lemma refusal_b_vmmaps : forall i m1 m2 r, m_vmmaps m1 = m_vmmaps m2 -> refusal_b i m1 r = refusal_b i m2 r.
Proof. intros i m1 m2 r E. unfold refusal_b, brk_refusal_b. rewrite E. reflexivity. Qed.

Lemma spurious_relX : forall i mo matl (chk : resp -> Model -> check_result) eff,
  (forall eff m, check_syscall i eff m = chk eff m) ->
  (forall eff, relX mo matl (chk eff (MX mo matl)) (chk eff mo)) ->
  spurious_refusal_cfg ACFG i (MX mo matl) eff <-> spurious_refusal_cfg ACFG i mo eff.
Proof.
  intros i mo matl chk eff Hchk Hx.
  assert (Hr : forall r, refusal_b i (MX mo matl) r = refusal_b i mo r)
    by (intros r; apply refusal_b_vmmaps; apply m_vmmaps_MX).
  split.
  - intros (Hf & Hrf & (eff' & m' & evs' & Hs & Hnr)). rewrite Hr in Hrf. rewrite Hr in Hnr.
    split; [exact Hf|]. split; [exact Hrf|].
    apply check_syscall_ok_iff in Hs. rewrite Hchk in Hs. pose proof (Hx eff') as R. rewrite Hs in R.
    apply relX_ok_l in R as (m & f & Hc & _).
    exists eff', m, evs'. split; [apply check_syscall_ok_iff; rewrite Hchk; exact Hc| exact Hnr].
  - intros (Hf & Hrf & (eff' & m' & evs' & Hs & Hnr)).
    split; [exact Hf|]. split; [rewrite Hr; exact Hrf|].
    apply check_syscall_ok_iff in Hs. rewrite Hchk in Hs. pose proof (Hx eff') as R. rewrite Hs in R.
    apply relX_ok_r in R as (_ & f & Hc & _).
    exists eff', (MX m' (List.filter f matl)), evs'.
    split; [apply check_syscall_ok_iff; rewrite Hchk; exact Hc| rewrite Hr; exact Hnr].
Qed.

