  Ltac init_sp_solve :=
    rewrite ?vmmaps_with_mmap_replacement, ?vmmaps_with_mmap_backing, ?m_vmmaps_with_mmap_destroyedA,
            ?m_vmmaps_with_vmmaps; try reflexivity.
