  Lemma factsA_ns_of_old : forall n,
    node_factsA A RNG ms mo mo_ n ->
    (exists x8', ms_svc_pending ms = Some x8' /\ ~ In (bv_unsigned x8') alloc_mark_sysnos) ->
    node_factsA_ns A RNG ms mo mo_ n.
  Proof.
    intros n (x8 & Hsvc & Hok & Hcpl & Hnu & Hpres & Hdet) (x8' & Hsvc' & Hnin).
    rewrite Hsvc in Hsvc'. injection Hsvc' as <-.
    exists x8. split; [exact Hsvc|].
    split; [|split; [|split; [|split; [exact Hnu| split; [exact Hpres| exact Hdet]]]]].
    - intros eff moX evs Hc _. exact (Hok _ _ _ Hc).
    - intros eff moX evs Hc. eapply succ_ok_halted; [exact (Hok _ _ _ Hc)|].
      intros eff' mo' evs' Hn. exact (proj1 (Hpres _ _ _ Hn)).
    - intros eff mo' evs Hn. destruct (Hcpl _ _ _ Hn) as (effk & moX & Hc & Hr).
      exists effk, moX. split; [exact Hc|]. split; [exact Hr|]. apply acfg_nonspurious. exact Hnin.
  Qed.

  Lemma all_factsA : forall n,
    match n with NExit _ => False | _ => True end ->
    at_nodeA segs n RNG ms -> nsafeA NMAX n mo -> node_factsA_ns A RNG ms mo mo_ n.
  Proof.
    intros n Hne Hat Hsafe. destruct (alloc_node n) eqn:Ha.
    - destruct n; try discriminate Ha.
      + apply brk_factsA; assumption.
      + apply mmap_factsA; assumption.
      + apply mprotect_factsA; assumption.
    - apply factsA_ns_of_old.
      + destruct n; try contradiction; try discriminate Ha;
          first [ apply write_factsA | apply writev_factsA | apply open_factsA | apply read_factsA
                | apply close_factsA | apply ioctl_factsA | apply set_tid_factsA | apply munmap_factsA
                | apply madvise_factsA ]; assumption.
      + apply (at_node_nonalloc_svc segs n ms Ha). eapply at_nodeA_at_node; [| exact Hat].
        destruct n; first [discriminate Ha | exact I].
  Qed.
End Common.
